from pathlib import Path
import os,json,hashlib,base64
from playwright.sync_api import sync_playwright
R=Path(__file__).resolve().parents[2];O=R/'qa/combat-head';h=(R/'dist/INK-Street-Fighter-6.html').read_bytes();sha=hashlib.sha256(h).hexdigest();rows=[];images=[]
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path=os.environ['INK_CHROMIUM'],headless=True);p=b.new_page(viewport={'width':1440,'height':1000});p.set_content(h.decode());p.wait_for_function('window.INKDuel?.ready&&INK.CombatHead');p.locator('.kinetic-launch button').click()
